INSERT INTO product_categories(id,code,name) SELECT gen_random_uuid(),v.code,v.name FROM (VALUES ('MED','ยาแผนปัจจุบัน'),('HER','ยาสมุนไพร'),('SUP','เวชภัณฑ์'),('VIT','วิตามิน'),('NUT','ผลิตภัณฑ์โภชนาการ'),('COS','ผลิตภัณฑ์ดูแลผิว'),('DEN','ทันตกรรม'),('LAB','อุปกรณ์ห้องปฏิบัติการ'),('EQP','เครื่องมือแพทย์'),('SAN','ผลิตภัณฑ์ทำความสะอาด'),('REH','อุปกรณ์ฟื้นฟู'),('PED','ผลิตภัณฑ์สำหรับเด็ก'),('VET','เวชภัณฑ์สัตว์'),('WND','อุปกรณ์ดูแลแผล'),('GEN','ผลิตภัณฑ์ทั่วไป')) v(code,name) WHERE NOT EXISTS(SELECT 1 FROM product_categories t WHERE t.code=v.code OR t.name=v.name) ON CONFLICT DO NOTHING;
INSERT INTO dosage_forms(id,code,name) SELECT gen_random_uuid(),v.code,v.name FROM (VALUES ('TAB','ยาเม็ด'),('CAP','แคปซูล'),('SYR','น้ำเชื่อม'),('INJ','ยาฉีด'),('CRM','ครีม'),('GEL','เจล'),('OIN','ขี้ผึ้ง'),('DRP','ยาหยด'),('SPR','สเปรย์'),('PWD','ผง'),('SOL','สารละลาย'),('SUS','ยาน้ำแขวนตะกอน'),('SUP','ยาเหน็บ'),('PAD','แผ่น'),('DEV','อุปกรณ์')) v(code,name) WHERE NOT EXISTS(SELECT 1 FROM dosage_forms t WHERE t.code=v.code OR t.name=v.name) ON CONFLICT DO NOTHING;
INSERT INTO warehouses(id,code,name) SELECT gen_random_uuid(),v.code,v.name FROM (VALUES ('WH-INIT-01','คลัง 01'),('WH-INIT-02','คลัง 02'),('WH-INIT-03','คลัง 03'),('WH-INIT-04','คลัง 04'),('WH-INIT-05','คลัง 05'),('WH-INIT-06','คลัง 06'),('WH-INIT-07','คลัง 07'),('WH-INIT-08','คลัง 08'),('WH-INIT-09','คลัง 09'),('WH-INIT-10','คลัง 10'),('WH-INIT-11','คลัง 11'),('WH-INIT-12','คลัง 12'),('WH-INIT-13','คลัง 13'),('WH-INIT-14','คลัง 14'),('WH-INIT-15','คลัง 15')) v(code,name) WHERE NOT EXISTS(SELECT 1 FROM warehouses t WHERE t.code=v.code OR t.name=v.name) ON CONFLICT DO NOTHING;
INSERT INTO drugs(id,name) VALUES (gen_random_uuid(),'Paracetamol'),(gen_random_uuid(),'Cetirizine'),(gen_random_uuid(),'Loratadine'),(gen_random_uuid(),'Ibuprofen'),(gen_random_uuid(),'Amoxicillin'),(gen_random_uuid(),'Omeprazole'),(gen_random_uuid(),'Metformin'),(gen_random_uuid(),'Amlodipine'),(gen_random_uuid(),'Losartan'),(gen_random_uuid(),'Atorvastatin'),(gen_random_uuid(),'Vitamin C'),(gen_random_uuid(),'Calcium carbonate'),(gen_random_uuid(),'Zinc sulfate'),(gen_random_uuid(),'Oral rehydration salts'),(gen_random_uuid(),'Normal saline') ON CONFLICT(name) DO NOTHING;
INSERT INTO "customer_groups"(id,"code","name","status","category","description","owner","notes") SELECT gen_random_uuid(),'GRP-INIT-'||lpad(n::text,3,'0'),'กลุ่มลูกค้า '||lpad(n::text,3,'0'),'ใช้งานอยู่','ทั่วไป','','','' FROM (SELECT n FROM generate_series(1,10000) n WHERE NOT EXISTS(SELECT 1 FROM "customer_groups" existing WHERE existing.code='GRP-INIT-'||lpad(n::text,3,'0')) ORDER BY n LIMIT greatest(0,15-(SELECT count(*)::int FROM "customer_groups" WHERE deleted_at IS NULL))) candidates ON CONFLICT(code) DO NOTHING;
INSERT INTO "sales_territories"(id,"code","name","status","area","owner","notes") SELECT gen_random_uuid(),'TER-INIT-'||lpad(n::text,3,'0'),'เขตและผู้แทนขาย '||lpad(n::text,3,'0'),'ใช้งานอยู่','','','' FROM (SELECT n FROM generate_series(1,10000) n WHERE NOT EXISTS(SELECT 1 FROM "sales_territories" existing WHERE existing.code='TER-INIT-'||lpad(n::text,3,'0')) ORDER BY n LIMIT greatest(0,15-(SELECT count(*)::int FROM "sales_territories" WHERE deleted_at IS NULL))) candidates ON CONFLICT(code) DO NOTHING;
INSERT INTO "suppliers"(id,"code","name","status","category","location","contact","payment_terms","notes") SELECT gen_random_uuid(),'SUP-INIT-'||lpad(n::text,3,'0'),'ผู้ขาย '||lpad(n::text,3,'0'),'ใช้งานอยู่','ผู้จำหน่าย','กรุงเทพมหานคร','','','' FROM (SELECT n FROM generate_series(1,10000) n WHERE NOT EXISTS(SELECT 1 FROM "suppliers" existing WHERE existing.code='SUP-INIT-'||lpad(n::text,3,'0')) ORDER BY n LIMIT greatest(0,15-(SELECT count(*)::int FROM "suppliers" WHERE deleted_at IS NULL))) candidates ON CONFLICT(code) DO NOTHING;
INSERT INTO "customers"(id,"code","name","status","category","province","owner","payment_terms","group_id","territory_id","notes") SELECT gen_random_uuid(),'CUS-INIT-'||lpad(n::text,3,'0'),'องค์กรลูกค้า '||lpad(n::text,3,'0'),'ใช้งานอยู่','องค์กร','กรุงเทพมหานคร','','',(SELECT id FROM "customer_groups" WHERE deleted_at IS NULL ORDER BY code OFFSET ((n-1)%greatest(1,(SELECT count(*)::int FROM "customer_groups" WHERE deleted_at IS NULL))) LIMIT 1),(SELECT id FROM "sales_territories" WHERE deleted_at IS NULL ORDER BY code OFFSET ((n-1)%greatest(1,(SELECT count(*)::int FROM "sales_territories" WHERE deleted_at IS NULL))) LIMIT 1),'' FROM (SELECT n FROM generate_series(1,10000) n WHERE NOT EXISTS(SELECT 1 FROM "customers" existing WHERE existing.code='CUS-INIT-'||lpad(n::text,3,'0')) ORDER BY n LIMIT greatest(0,15-(SELECT count(*)::int FROM "customers" WHERE deleted_at IS NULL))) candidates ON CONFLICT(code) DO NOTHING;
INSERT INTO "customer_documents"(id,"code","name","status","customer_id","document_type","date_text","file_url","owner","notes") SELECT gen_random_uuid(),'DOC-INIT-'||lpad(n::text,3,'0'),'เอกสารลูกค้า '||lpad(n::text,3,'0'),'ร่าง',(SELECT id FROM "customers" WHERE deleted_at IS NULL ORDER BY code OFFSET ((n-1)%greatest(1,(SELECT count(*)::int FROM "customers" WHERE deleted_at IS NULL))) LIMIT 1),'ข้อมูลลูกค้า','','','','' FROM (SELECT n FROM generate_series(1,10000) n WHERE NOT EXISTS(SELECT 1 FROM "customer_documents" existing WHERE existing.code='DOC-INIT-'||lpad(n::text,3,'0')) ORDER BY n LIMIT greatest(0,15-(SELECT count(*)::int FROM "customer_documents" WHERE deleted_at IS NULL))) candidates ON CONFLICT(code) DO NOTHING;
INSERT INTO "customer_follow_ups"(id,"code","name","status","customer_id","category","province","follow_up_text","owner","notes") SELECT gen_random_uuid(),'FUP-INIT-'||lpad(n::text,3,'0'),'ภาพรวมลูกค้า '||lpad(n::text,3,'0'),'ร่าง',(SELECT id FROM "customers" WHERE deleted_at IS NULL ORDER BY code OFFSET ((n-1)%greatest(1,(SELECT count(*)::int FROM "customers" WHERE deleted_at IS NULL))) LIMIT 1),'ทั่วไป','กรุงเทพมหานคร','รอบันทึกข้อมูลติดตาม','','' FROM (SELECT n FROM generate_series(1,10000) n WHERE NOT EXISTS(SELECT 1 FROM "customer_follow_ups" existing WHERE existing.code='FUP-INIT-'||lpad(n::text,3,'0')) ORDER BY n LIMIT greatest(0,15-(SELECT count(*)::int FROM "customer_follow_ups" WHERE deleted_at IS NULL))) candidates ON CONFLICT(code) DO NOTHING;
INSERT INTO "expenses"(id,"code","name","status","category","description","owner","amount","notes") SELECT gen_random_uuid(),'EXP-INIT-'||lpad(n::text,3,'0'),'ค่าใช้จ่าย '||lpad(n::text,3,'0'),'ร่าง','ค่าใช้จ่ายทั่วไป','','',NULL,'' FROM (SELECT n FROM generate_series(1,10000) n WHERE NOT EXISTS(SELECT 1 FROM "expenses" existing WHERE existing.code='EXP-INIT-'||lpad(n::text,3,'0')) ORDER BY n LIMIT greatest(0,15-(SELECT count(*)::int FROM "expenses" WHERE deleted_at IS NULL))) candidates ON CONFLICT(code) DO NOTHING;
INSERT INTO "purchase_orders"(id,"code","name","status","supplier_id","description","owner","amount","notes") SELECT gen_random_uuid(),'PO-INIT-'||lpad(n::text,3,'0'),'จัดซื้อและรับเข้าสินค้า '||lpad(n::text,3,'0'),'ร่าง',(SELECT id FROM "suppliers" WHERE deleted_at IS NULL ORDER BY code OFFSET ((n-1)%greatest(1,(SELECT count(*)::int FROM "suppliers" WHERE deleted_at IS NULL))) LIMIT 1),'','',NULL,'' FROM (SELECT n FROM generate_series(1,10000) n WHERE NOT EXISTS(SELECT 1 FROM "purchase_orders" existing WHERE existing.code='PO-INIT-'||lpad(n::text,3,'0')) ORDER BY n LIMIT greatest(0,15-(SELECT count(*)::int FROM "purchase_orders" WHERE deleted_at IS NULL))) candidates ON CONFLICT(code) DO NOTHING;
INSERT INTO "quotations"(id,"code","name","status","customer_id","description","owner","amount","notes") SELECT gen_random_uuid(),'QT-INIT-'||lpad(n::text,3,'0'),'ใบเสนอราคา '||lpad(n::text,3,'0'),'ร่าง',(SELECT id FROM "customers" WHERE deleted_at IS NULL ORDER BY code OFFSET ((n-1)%greatest(1,(SELECT count(*)::int FROM "customers" WHERE deleted_at IS NULL))) LIMIT 1),'','',NULL,'' FROM (SELECT n FROM generate_series(1,10000) n WHERE NOT EXISTS(SELECT 1 FROM "quotations" existing WHERE existing.code='QT-INIT-'||lpad(n::text,3,'0')) ORDER BY n LIMIT greatest(0,15-(SELECT count(*)::int FROM "quotations" WHERE deleted_at IS NULL))) candidates ON CONFLICT(code) DO NOTHING;
INSERT INTO "sales_orders"(id,"code","name","status","customer_id","description","owner","amount","notes") SELECT gen_random_uuid(),'SO-INIT-'||lpad(n::text,3,'0'),'คำสั่งซื้อและจัดส่ง '||lpad(n::text,3,'0'),'ร่าง',(SELECT id FROM "customers" WHERE deleted_at IS NULL ORDER BY code OFFSET ((n-1)%greatest(1,(SELECT count(*)::int FROM "customers" WHERE deleted_at IS NULL))) LIMIT 1),'','',NULL,'' FROM (SELECT n FROM generate_series(1,10000) n WHERE NOT EXISTS(SELECT 1 FROM "sales_orders" existing WHERE existing.code='SO-INIT-'||lpad(n::text,3,'0')) ORDER BY n LIMIT greatest(0,15-(SELECT count(*)::int FROM "sales_orders" WHERE deleted_at IS NULL))) candidates ON CONFLICT(code) DO NOTHING;
INSERT INTO "invoices"(id,"code","name","status","customer_id","due_text","owner","amount","notes") SELECT gen_random_uuid(),'INV-INIT-'||lpad(n::text,3,'0'),'วางบิลและลูกหนี้ '||lpad(n::text,3,'0'),'ร่าง',(SELECT id FROM "customers" WHERE deleted_at IS NULL ORDER BY code OFFSET ((n-1)%greatest(1,(SELECT count(*)::int FROM "customers" WHERE deleted_at IS NULL))) LIMIT 1),'','',NULL,'' FROM (SELECT n FROM generate_series(1,10000) n WHERE NOT EXISTS(SELECT 1 FROM "invoices" existing WHERE existing.code='INV-INIT-'||lpad(n::text,3,'0')) ORDER BY n LIMIT greatest(0,15-(SELECT count(*)::int FROM "invoices" WHERE deleted_at IS NULL))) candidates ON CONFLICT(code) DO NOTHING;
