INSERT INTO "stock_count_sessions"(id,"code","name","status","warehouse_id","description","owner","result_text","notes") SELECT gen_random_uuid(),'CNT-INIT-'||lpad(n::text,3,'0'),'ตรวจนับสินค้า '||lpad(n::text,3,'0'),'ร่าง',(SELECT id FROM "warehouses"  ORDER BY code OFFSET ((n-1)%greatest(1,(SELECT count(*)::int FROM "warehouses" ))) LIMIT 1),'','','','' FROM (SELECT n FROM generate_series(1,10000) n WHERE NOT EXISTS(SELECT 1 FROM "stock_count_sessions" existing WHERE existing.code='CNT-INIT-'||lpad(n::text,3,'0')) ORDER BY n LIMIT greatest(0,15-(SELECT count(*)::int FROM "stock_count_sessions" WHERE deleted_at IS NULL))) candidates ON CONFLICT(code) DO NOTHING;
