BEGIN;
LOCK TABLE "customers","customer_groups","sales_territories","customer_documents","customer_follow_ups","suppliers","expenses","purchase_orders","quotations","sales_orders","invoices","promotions","stock_count_sessions","system_settings",products,product_categories,dosage_forms,drugs,warehouses IN SHARE ROW EXCLUSIVE MODE;
DO $seed$ DECLARE i integer; cat_id uuid; cat_code text; form_id uuid; form_code text; drug_id uuid; drug_name text; warehouse_id uuid; seq integer; missing integer; BEGIN
 SELECT id,code INTO cat_id,cat_code FROM product_categories WHERE code='MED';
 SELECT id,code INTO form_id,form_code FROM dosage_forms WHERE code='TAB';
 SELECT id INTO warehouse_id FROM warehouses ORDER BY code LIMIT 1;
 SELECT greatest(0,15-count(*)::int) INTO missing FROM products WHERE deleted_at IS NULL;
 FOR i IN 1..missing LOOP
 SELECT id,name INTO drug_id,drug_name FROM drugs ORDER BY name OFFSET ((i-1)%(SELECT count(*)::int FROM drugs)) LIMIT 1;
 SELECT coalesce(max(sequence),0)+1 INTO seq FROM products WHERE category_id=cat_id AND dosage_form_id=form_id;
 IF seq>9999 THEN RAISE EXCEPTION 'Product sequence exhausted'; END IF;
 END LOOP;
 END $seed$;
COMMIT;
SELECT (SELECT count(*)::int FROM "customers" WHERE deleted_at IS NULL) AS "customers",(SELECT count(*)::int FROM "customer_groups" WHERE deleted_at IS NULL) AS "customer-groups",(SELECT count(*)::int FROM "sales_territories" WHERE deleted_at IS NULL) AS "sales-territories",(SELECT count(*)::int FROM "customer_documents" WHERE deleted_at IS NULL) AS "customer-documents",(SELECT count(*)::int FROM "customer_follow_ups" WHERE deleted_at IS NULL) AS "customer-follow-ups",(SELECT count(*)::int FROM "suppliers" WHERE deleted_at IS NULL) AS "suppliers",(SELECT count(*)::int FROM "expenses" WHERE deleted_at IS NULL) AS "expenses",(SELECT count(*)::int FROM "purchase_orders" WHERE deleted_at IS NULL) AS "purchases",(SELECT count(*)::int FROM "quotations" WHERE deleted_at IS NULL) AS "quotes",(SELECT count(*)::int FROM "sales_orders" WHERE deleted_at IS NULL) AS "orders",(SELECT count(*)::int FROM "invoices" WHERE deleted_at IS NULL) AS "billing",(SELECT count(*)::int FROM "promotions" WHERE deleted_at IS NULL) AS "promotions",(SELECT count(*)::int FROM "stock_count_sessions" WHERE deleted_at IS NULL) AS "stock-counts",(SELECT count(*)::int FROM "system_settings" WHERE deleted_at IS NULL) AS "settings",(SELECT count(*)::int FROM products WHERE deleted_at IS NULL) products,(SELECT count(*)::int FROM product_categories) categories,(SELECT count(*)::int FROM dosage_forms) dosage_forms,(SELECT count(*)::int FROM drugs) drugs,(SELECT count(*)::int FROM warehouses) warehouses;
